// Writes src/races.gen.ts: the race models the game modes play (data/pools.json: the daily,
// survivor and eras pools, plus versus mode's tracks), bundled into the Worker (Phase 4 spec
// A2). Races in no pool (validation only) stay out, which keeps the Worker small. CI checks the
// generated file is up to date.
//
// RACE_FILES holds the Daily and Gauntlet races and versus mode's tracks, exactly as before
// Eras (GET /api/races serves them). ERAS_RACE_FILES holds the Eras races that are in neither of those pools and already
// have a race file in data/races: most Eras races aren't built yet, and are skipped until they
// are. They're served only through the Eras API, which keeps Draft races off production.
// ERAS_OVERLAYS holds the Eras overlays (data/eras/<race-id>.json) of the races in Eras and in
// RACE_FILES (the shared races): their race files stay the Daily ones, and the Eras API serves
// them merged with the overlay (src/erasOverlay.ts; eras build plan, "Shared races").
//   pnpm --filter @laststint/worker races
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { RaceModel } from '@laststint/sim';
import { withErasOverlay } from '../src/erasOverlay.js';

const here = dirname(fileURLToPath(import.meta.url));
const races = join(here, '..', '..', '..', 'data', 'races');
const pools = JSON.parse(readFileSync(join(races, '..', 'pools.json'), 'utf8')) as {
  daily: string[];
  survivor: Record<string, number[]>;
  eras: Record<string, string[]>;
};
// Versus mode's tracks run on these race files (packages/sim/src/versus.ts VERSUS_TRACKS).
const versus = ['italy-2024', 'belgium-2024', 'bahrain-2022', 'japan-2024', 'hungary-2025'];
const ids = [...new Set([...pools.daily, ...Object.keys(pools.survivor), ...versus])].sort();
const bundled = new Set(ids);
const erasAll = Object.values(pools.eras).flat();
const erasIds = erasAll
  .filter((id) => !bundled.has(id) && existsSync(join(races, `${id}.json`)))
  .sort();
const erasMissing = erasAll.filter((id) => !bundled.has(id) && !erasIds.includes(id)).length;
const overlays = join(races, '..', 'eras');
const sharedIds = [...new Set(erasAll)]
  .filter((id) => bundled.has(id) && existsSync(join(overlays, `${id}.json`)))
  .sort();
// An overlay the Worker couldn't merge fails here, not on the first Eras attempt.
for (const id of sharedIds) {
  const read = (path: string) => JSON.parse(readFileSync(path, 'utf8'));
  withErasOverlay(read(join(races, `${id}.json`)) as RaceModel, read(join(overlays, `${id}.json`)));
}

const lines = [
  '// Generated by `pnpm --filter @laststint/worker races` from data/pools.json. Do not edit.',
  '',
  // One import list in path order (the linter sorts imports), both pools interleaved.
  ...[
    ...ids.map((id, i) => ({ path: `races/${id}`, name: `r${i}` })),
    ...erasIds.map((id, i) => ({ path: `races/${id}`, name: `e${i}` })),
    ...sharedIds.map((id, i) => ({ path: `eras/${id}`, name: `o${i}` })),
  ]
    .sort((a, b) => (a.path < b.path ? -1 : 1))
    .map(({ path, name }) => `import ${name} from '../../../data/${path}.json';`),
  '',
  'export const RACE_FILES: Record<string, unknown> = {',
  ...ids.map((id, i) => `  '${id}': r${i},`),
  '};',
  '',
  '/** Eras races in no Daily or Gauntlet pool that have a race file (served by the Eras API). */',
  'export const ERAS_RACE_FILES: Record<string, unknown> = {',
  ...erasIds.map((id, i) => `  '${id}': e${i},`),
  '};',
  '',
  '/** The Eras overlays of the races in Eras and in RACE_FILES (merged in by the Eras API). */',
  'export const ERAS_OVERLAYS: Record<string, unknown> = {',
  ...sharedIds.map((id, i) => `  '${id}': o${i},`),
  '};',
  '',
];
writeFileSync(join(here, '..', 'src', 'races.gen.ts'), lines.join('\n'));
console.log(
  `bundled ${ids.length} races, ${erasIds.length} Eras-only races (${erasMissing} Eras races have no file yet) and ${sharedIds.length} shared races' Eras overlays`,
);
